public double getBonificacao() {
    return this.salario * 0.15;
}
// ...
}

public class Gerente extends Funcionario {
    int senha;
    int numeroDeFuncionariosGerenciados;
    public double getBonificacao() {
        return this.salario * 0.10 + 1000;
    }
    // ...
}

